import * as PIXI from 'pixi.js';

export class Slide extends PIXI.Container {
    public slideIndex!: number;

    protected transitionSlideInCallback!: (delay: number, isAutoPlayTransition: boolean) => void;
    protected transitionSlideLeftCallback!: (isAutoPlayTransition: boolean) => void;
    protected transitionInDelay: number;

    constructor() {
        super();

        this.transitionInDelay = 0;
    }

    public setCallbacks(transitionSlideInCallback: () => void, transitionSlideLeftCallback: (autoPlay: boolean) => void, slideIndex: number): Promise<void> {
        return new Promise((resolve) => {
            this.transitionSlideInCallback = transitionSlideInCallback;
            this.transitionSlideLeftCallback = transitionSlideLeftCallback;
            this.slideIndex = slideIndex;

            return resolve();
        });
    }

    public handleOrientationChange(slideWidth: number, slideHeight: number, yPosition: number): void {
        this.position.y = yPosition;
    }

    protected onAnimationComplete(): void {
        this.transitionSlideLeftCallback(true);
        this.transitionSlideInCallback(this.transitionInDelay, true);
    }
}
